    if (count > MAX_ALLOWED_SIZE)
        return -EINVAL;

    struct device_info *dev = get_active_device();
    if (!dev)
        return -ENODEV;

    struct element_info *elem = allocate_element_info();
    if (!elem) {
        put_device(dev);
        return -ENOMEM;
    }

    if (copy_from_user(elem->data, buf, count)) {
        free_element_info(elem);
        put_device(dev);
        return -EFAULT;
