}

ssize_t dev_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    if (count > MAX_WRITE_SIZE)
        return -E2BIG;

    struct dev_lock *dev_lock;
    struct active_dev *active_dev;
    struct element_info *element_info;
    ssize_t bytes_written = 0;

    dev_lock = get_dev_lock();
    if (IS_ERR(dev_lock))
        return PTR_ERR(dev_lock);

    active_dev = get_active_dev(dev_lock);
    if (!active_dev) {
        release_dev_lock(dev_lock);
        return -ENODEV;
    }

    element_info = allocate_element_info();
    if (!element_info) {
        release_dev_lock(dev_lock);
        put_active_dev(active_dev);
        return -ENOMEM;
    }

    bytes_written = copy_from_user(element_info->data, buf, count);
    if (bytes_written != 0) {
        free_element_info(element_info);
        put_active_dev(active_dev);
        release_dev_lock(dev_lock);
        return -EFAULT;
    }

    element_info->seq_num = active_dev->seq_num++;
    enqueue_element(active_dev->queue, element_info);

    *fpos += count;

    put_active_dev(active_dev);
    release_dev_lock(dev_lock);

    return count;
}

ssize_t dev_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    if (count > MAX_ALLOWED_SIZE)
        return -EINVAL;

    struct active_device *dev;
    struct element_info *elem;
    ssize_t ret = 0;

    dev = acquire_active_device();
    if (!dev)
        return -ENODEV;

    elem = allocate_element_info();
    if (!elem) {
        release_active_device(dev);
        return -ENOMEM;
    }

    if (copy_from_user(elem->data, buf, count)) {
        ret = -EFAULT;
        goto cleanup;
    }

    elem->length = count;
    update_sequence_number(elem);

    if (!queue_element(elem)) {
        ret = -EIO;
        goto cleanup;
    }

    *fpos += count;
    ret = count;

cleanup:
    free_element_info(elem);
    release_active_device(dev);
    return ret;
}

ssize_t device_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    if (count > MAX_ALLOWED_SIZE) {
        return -EINVAL;
    }

    struct active_device *device;
    struct element_info *info;
    ssize_t bytes_written = 0;

    if (!try_module_get(THIS_MODULE)) {
        return -EFAULT;
    }

    device = get_active_device();
    if (!device || !device->is_connected) {
        module_put(THIS_MODULE);
        return -ENODEV;
    }

    info = kmalloc(sizeof(struct element_info), GFP_KERNEL);
    if (!info) {
        put_device(device);
        module_put(THIS_MODULE);
        return -ENOMEM;
    }

    info->sequence_number = get_next_sequence();

    if (copy_from_user(info->data, buf, count)) {
        kfree(info);
        put_device(device);
        module_put(THIS_MODULE);
        return -EFAULT;
    }

    bytes_written = enqueue_element(info);
    if (bytes_written <= 0) {
        kfree(info);
        put_device(device);
        module_put(THIS_MODULE);
        return 0;
    }

    *fpos += bytes_written;

    put_device(device);
    module_put(THIS_MODULE);
    return bytes_written;
}

ssize_t dev_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    struct active_dev *dev;
    struct elem_info *info;
    ssize_t bytes_written = 0;
    int ret;

    if (count > MAX_ALLOWED_SIZE)
        return -EINVAL;

    dev = get_active_dev();
    if (!dev)
        return -ENODEV;

    info = alloc_elem_info();
    if (!info) {
        put_active_dev(dev);
        return -ENOMEM;
    }

    ret = copy_from_user(info->data, buf, count);
    if (ret) {
        kfree(info);
        put_active_dev(dev);
        return -EFAULT;
    }

    update_seq_num(info);
    queue_elem(info);

    bytes_written = count;
    *fpos += count;

    put_active_dev(dev);
    free_elem_info(info);

    return bytes_written;
}
